<?php declare(strict_types=1);use FMonitor2\YiiRuntime\Assets\InstallerDirectoryAssetBundle;use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;InstallerDirectoryAssetBundle::register($this);$labels=['free'=>'Свободен','assigned'=>'1 активное закрепление','overloaded'=>'','unknown'=>'Нет достоверных данных'];$date=static fn(?string$v,string$unknown='Неизвестно'):string=>$v===null?$unknown:($v==='now'?'Сейчас':(new DateTimeImmutable($v))->format('d.m.Y'));$dateTime=static fn(string$v):string=>(new DateTimeImmutable($v))->setTimezone(new DateTimeZone('Europe/Moscow'))->format('d.m.Y H:i');ViewSupport::begin($this,(string)$installer['fio'],$identity,'installers');?><div class="fm2-page-header"><div><h1><?=Html::encode($installer['fio'])?></h1><p>таб. <?=str_pad((string)$installer['installer_tab_id'],6,'0',STR_PAD_LEFT)?> · <?=Html::encode($installer['position'])?></p></div><a class="shlz-button shlz-button--secondary" href="<?=Html::encode($returnUrl)?>">К списку монтажников</a></div><section class="fm2-installer-profile"><dl><div><dt>Кадровый статус</dt><dd>Работает</dd></div><div><dt>Активные закрепления</dt><dd><span class="fm2-utilization-status fm2-utilization-status--<?=$installer['load']?>"><?=$installer['load']==='overloaded'?count($installer['assignments']).' активных '.(count($installer['assignments'])<5?'закрепления':'закреплений'):$labels[$installer['load']]?></span></dd></div><div><dt>Позднейшее плановое окончание</dt><dd><?=$date($installer['planned_release'])?></dd></div><div><dt>Источник</dt><dd><?=Html::encode($installer['workforce_source'])?> · <?=$dateTime($installer['workforce_source_updated_at'])?></dd></div></dl></section><section class="fm2-list-surface fm2-installer-card-section"><h2>Текущая работа</h2><p data-current-work-count="<?=count($installer['assignments'])?>"><?=count($installer['assignments'])===0?'Нет текущих работ':count($installer['assignments']).' текущие работы'?></p><?php if($installer['assignments']===[]):?><p class="shlz-table__empty">Нет текущих работ</p><?php else:?><ul class="fm2-current-assignments"><?php foreach($installer['assignments']as$assignment):?><li><a class="shlz-link" href="/pilot/objects/<?=(int)$assignment['object_id']?>"><strong><?=Html::encode($assignment['registration_number'])?></strong><span><?=Html::encode($assignment['address'])?></span></a><small>Плановое завершение: <?=$date($assignment['planned_finish'])?></small></li><?php endforeach?></ul><?php endif?></section><section class="fm2-list-surface fm2-installer-card-section"><?php if($installer['upcomingAssignments']===[]):?><h2>Будущая загрузка</h2><p>Нет будущих назначений</p><?php else:?><h2>Предстоящее назначение</h2><?php foreach($installer['upcomingAssignments']as$future):?><p><a class="shlz-link" href="/pilot/objects/<?=(int)$future['object_id']?>"><?=Html::encode($future['registration_number'])?></a> · <?=Html::encode($future['address'])?> · <?=$future['planned_start']===null?'Дата начала неизвестна':$date($future['planned_start'])?></p><?php endforeach;endif?></section><section class="fm2-list-surface fm2-installer-card-section"><h2>История участия</h2><?php if($periods===[]):?><p class="shlz-table__empty">История закреплений отсутствует</p><?php else:?><ol class="fm2-utilization-timeline" data-utilization-timeline><?php foreach($periods as$period):?><li data-history-period data-object-id="<?=$period['object_id']?>" data-start="<?=Html::encode($period['start'])?>"><span class="fm2-timeline-range"><time><?=$date($period['start'])?></time><i aria-hidden="true"></i><time><?=$period['end']===null?'продолжается':$date($period['end'])?></time></span><a class="shlz-link" href="/pilot/objects/<?=$period['object_id']?>"><?=Html::encode($period['registration_number'])?></a><small><?=Html::encode($period['address'])?></small></li><?php endforeach?></ol><?php endif?><?=ViewSupport::pagination('/pilot/installers/'.$installer['installer_tab_id'],$history['page'],$history['pages'],$history['total'],50,[],'Страницы истории закреплений')?></section><?php ViewSupport::end($this);
